// 1. Obtiene el valor de una variable de entorno llamada "NombredelArchivo"
//    y lo almacena en la variable local 'archivo'
//    Ejemplo: si la variable de entorno vale "documento.pdf", archivo = "documento.pdf"
let archivo = env.get("NombredelArchivo");

// 2. Compara el nombre del archivo que viene en el payload (msg.payload.name)
//    con el valor de la variable de entorno que guardamos en 'archivo'
if(msg.payload.name == archivo){

    // 3. Si son iguales, establece msg.archivo = true (verdadero)
    msg.archivo = true;

    // 4. Y guarda el tamaño del archivo (stat.size) en msg.size
    msg.size = msg.payload.stat.size;
}
// 5. Si NO son iguales (else)
else {
    // 6. Establece msg.archivo = false (falso)
    msg.archivo = false;

    // 7. Y asigna 0 como tamaño
    msg.size = 0;
}

// 8. Devuelve el objeto msg modificado para que pase al siguiente nodo en Node-RED
return msg;

