// Crea un objeto Date con la fecha y hora actual del sistema
const fecha = new Date();

// Obtiene el año actual (ej: 2026)
const anio = fecha.getFullYear();

// Obtiene el mes actual (0=Enero, 11=Diciembre), suma 1 para convertirlo a mes real,
// luego agrega un '0' al inicio y finalmente toma los últimos 2 caracteres.
// Ej: mes=3 -> '04' ; mes=12 -> '13'?.slice(-2) da '13' (corregido con operador ternario idealmente, pero funciona)
const mes = ('0' + (fecha.getMonth() + 1)).slice(-2);

// Obtiene el día del mes (1-31), agrega un '0' al inicio y toma últimos 2 dígitos.
// Ej: día=5 -> '05' ; día=25 -> '25'
const dia = ('0' + (fecha.getDate())).slice(-2);

// Obtiene la hora (0-23), formatea a 2 dígitos.
// Ej: hora=3 -> '03' ; hora=15 -> '15'
const hora = ('0' + (fecha.getHours())).slice(-2);

// Obtiene los minutos (0-59), formatea a 2 dígitos.
const minutos = ('0' + (fecha.getMinutes())).slice(-2);

// Obtiene los segundos (0-59), formatea a 2 dígitos.
const segundos = ('0' + (fecha.getSeconds())).slice(-2);

// Construye un string con el formato: AAAA-MM-DD-HH-MM-SS
// Ej: 2026-05-29-14-05-32
let timestamp = anio + '-' + mes + '-' + dia + ' ' + hora + ':' + minutos + ':' + segundos;

// Guarda el timestamp en el contexto del flujo (flow)
// Así otros nodos del mismo flow pueden acceder a flow.get("timestamp")
flow.set("timestamp", timestamp);

// Asigna el timestamp al payload del mensaje
// Esto envía el valor al siguiente nodo en Node-RED
msg.payload = timestamp;

// El objeto msg se devuelve implícitamente al final del bloque de función
return msg;

// Recuperamos las variables del flow (contexto del flujo en Node-RED)
// flow.get() obtiene valores previamente guardados con flow.set()
let timestamp = flow.get("timestamp");  // Obtiene la fecha/hora guardada (string)
let voltaje = flow.get("voltaje");      // Obtiene el valor de voltaje guardado (number)
let corriente = flow.get("corriente");  // Obtiene el valor de corriente guardado (number)
let potencia = flow.get("potencia");    // Obtiene el valor de potencia guardado (number)

// Convertimos a valores numéricos por si acaso (por si vienen como string o undefined)
// parseFloat() convierte string a número decimal (ej: "220.5" → 220.5)
// || 0 significa: si el resultado es NaN o undefined, usa 0 como valor por defecto
voltaje = parseFloat(voltaje) || 0;      // Convierte voltaje a número, si falla asigna 0
corriente = parseFloat(corriente) || 0;  // Convierte corriente a número, si falla asigna 0
potencia = parseFloat(potencia) || 0;    // Convierte potencia a número, si falla asigna 0

// Si no hay timestamp (es undefined, null o false), creamos uno nuevo
if (!timestamp) {  // ! significa "no" o "negación", !timestamp es verdadero si timestamp está vacío
    const fecha = new Date();  // Crea un objeto Date con la fecha y hora ACTUAL del sistema

    // Obtiene el año (ej: 2026)
    const anio = fecha.getFullYear();

    // Obtiene el mes: getMonth() devuelve 0-11 (0=Enero), por eso sumamos 1
    // ('0' + ...) agrega un '0' al inicio, .slice(-2) toma los últimos 2 caracteres
    // Ej: mes=3 → '0'+'4' = '04' → '04'; mes=12 → '0'+'13' = '013' → '13'
    const mes = ('0' + (fecha.getMonth() + 1)).slice(-2);

    // Obtiene el día del mes (1-31) y formatea a 2 dígitos
    // Ej: día=5 → '05'; día=25 → '25'
    const dia = ('0' + (fecha.getDate())).slice(-2);

    // Obtiene la hora (0-23) y formatea a 2 dígitos
    // Ej: hora=3 → '03'; hora=15 → '15'
    const hora = ('0' + (fecha.getHours())).slice(-2);

    // Obtiene los minutos (0-59) y formatea a 2 dígitos
    const minutos = ('0' + (fecha.getMinutes())).slice(-2);

    // Obtiene los segundos (0-59) y formatea a 2 dígitos
    const segundos = ('0' + (fecha.getSeconds())).slice(-2);

    // Template string (usando backticks `) para armar el timestamp
    // ${variable} inserta el valor de la variable dentro del string
    // Formato: AÑO-MES-DÍA HORA:MINUTOS:SEGUNDOS (ej: 2026-05-30 20:29:30)
    timestamp = `${anio}-${mes}-${dia} ${hora}:${minutos}:${segundos}`;
}

// node.log() envía un mensaje a la consola de Node-RED (pestaña Debug)
// Esto es útil para depurar y ver qué valores se están procesando
// Puedes eliminar estas líneas cuando el flujo funcione correctamente
