// El orden debe coincidir con el encabezado: TimeStamp,Voltaje,Corriente,Potencia
// msg.payload es la propiedad que pasa al siguiente nodo en Node-RED
msg.payload = [timestamp, voltaje, corriente, potencia];

// return msg; es implícito en Node-RED (no es necesario escribirlo, pero funciona)
// Devuelve el mensaje al siguiente nodo en el flujo
return msg;








