// Crea un objeto Date con la fecha y hora actual del sistema
const fecha = new Date();

// Obtiene el año actual (ej: 2026)
const anio = fecha.getFullYear();

// Obtiene el mes actual (0=Enero, 11=Diciembre), suma 1 para convertirlo a mes real,
// luego agrega un '0' al inicio y finalmente toma los últimos 2 caracteres.
// Ej: mes=3 -> '04' ; mes=12 -> '13'?.slice(-2) da '13' (corregido con operador ternario idealmente, pero funciona)
const mes = ('0' + (fecha.getMonth() + 1)).slice(-2);

// Obtiene el día del mes (1-31), agrega un '0' al inicio y toma últimos 2 dígitos.
// Ej: día=5 -> '05' ; día=25 -> '25'
const dia = ('0' + (fecha.getDate())).slice(-2);

// Obtiene la hora (0-23), formatea a 2 dígitos.
// Ej: hora=3 -> '03' ; hora=15 -> '15'
const hora = ('0' + (fecha.getHours())).slice(-2);

// Obtiene los minutos (0-59), formatea a 2 dígitos.
const minutos = ('0' + (fecha.getMinutes())).slice(-2);

// Obtiene los segundos (0-59), formatea a 2 dígitos.
const segundos = ('0' + (fecha.getSeconds())).slice(-2);

// Construye un string con el formato: AAAA-MM-DD-HH-MM-SS
// Ej: 2026-05-29-14-05-32
let timestamp = anio + '-' + mes + '-' + dia + ' ' + hora + ':' + minutos + ':' + segundos;

// Guarda el timestamp en el contexto del flujo (flow)
// Así otros nodos del mismo flow pueden acceder a flow.get("timestamp")
flow.set("timestamp", timestamp);

// Asigna el timestamp al payload del mensaje
// Esto envía el valor al siguiente nodo en Node-RED
msg.payload = timestamp;

// El objeto msg se devuelve implícitamente al final del bloque de función
return msg;
